// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    MultiplicatorX4 c;
    function setUp() public { c = new MultiplicatorX4(); }
    function testFuzz_property(uint256 amount, address target) public {
        vm.assume(amount > 0);
        vm.assume(target != address(c));
        vm.assume(target != address(0));
        address owner = c.Owner();
        vm.deal(owner, amount);
        uint256 balBefore = address(c).balance;
        vm.prank(owner);
        c.Command{value: amount}(target, "");
        uint256 balAfter = address(c).balance;
        assertTrue(balAfter <= balBefore);
    }
}
